/// What the host advertises over Bonjour while it listens on the local
/// network: `_switchboard._tcp` under an instance name, with TXT records
/// a client can match against a known server before it connects. Never
/// a token, never key material: the key hash is read from `/info` over
/// the pinned connection, not from a multicast record anyone can send.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Advertisement {
    /// The Bonjour instance name: the display name with a short id
    /// suffix, so two installations on one machine stay distinct.
    pub instance: String,
    pub server_id: Uuid,
    pub server_name: String,
    pub port: u16,
}

impl Advertisement {
    /// The service type, as the client browses for it.
    pub const SERVICE: &'static str = "_switchboard._tcp";
    fn remote_subscribe(
        &mut self,
        request: &RemoteRequest,
        device: uuid::Uuid,
        subscriber: Option<SubscriberQueue>,
    ) -> RemoteReply {
        let Some(queue) = subscriber.filter(|_| request.upgrade.is_some()) else {
            return self.refuse(
                request,
                400,
                "upgrade_required",
                "events are a WebSocket; upgrade the connection",
                true,
            );
        };
        let hello = self.event_json("hello", None, epoch_millis(SystemTime::now()));
        if queue.tx.try_send(hello).is_err() {
            return self.refuse(
                request,
                503,
                "busy",
                "the subscription could not start",
                true,
            );
        }
        self.subscribers.push(Subscriber {
            id: queue.id,
            queue,
            device,
            all: request.param("scope") == Some("all"),
        });
        RemoteReply {
            status: remote::SUBSCRIBED,
            body: Vec::new(),
            authenticated: true,
        }
    }

